  if (!(await this.readDone())) return;
  const lines = [['name', 'grade', 'retired-from', 'due-total']];
  for (const p of this.people()) {
    lines.push([p.name, this.gradeNow(p), p.retiredFrom ?? '', this.dueTotalOf(p) ?? 'n/a']);
  }
  this.downloadCsv('people.csv', lines);
}

/** Download every claim as a CSV file: people in list order, retired people included, and each
 *  person's claims oldest first, with number, date, amount, due, status and period as each claim
 *  shows them (a blank number or period, and a due of n/a, as they show). */
protected async exportClaims(): Promise<void> {
  if (!(await this.readDone())) return;
  const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
  for (const p of this.people()) {
    for (const c of [...this.claimsOf(p.id)].reverse()) {
      const due = claimShownCents(c, this.rates(), p.grades, this.floors(), this.lateness(), this.roundingOf(p.id));
      const period = periodOn(this.periods(), c.dueBy)?.name ?? '';
      lines.push([p.name, c.number ?? '', c.date, c.amount, due === null ? 'n/a' : money(due), c.status, period]);
    }
  }
  this.downloadCsv('claims.csv', lines);
}

/** Download the period figures as a CSV file: people in list order, retired people included, and
 *  for each the periods in the order added, with the figure and carried figure as the row shows them. */
protected async exportPeriods(): Promise<void> {
  if (!(await this.readDone())) return;
  const lines = [['person', 'period', 'figure', 'carried']];
  const added = [...this.periods()].sort((a, b) => a.id - b.id);
  for (const p of this.people()) {
    for (const pd of added) {
      const figure = this.personPeriodCents().get(p.id)?.[pd.name] ?? 0;
      const carried = this.personCarriedCents().get(p.id)?.[pd.name] ?? 0;
      lines.push([p.name, pd.name, money(figure), money(carried)]);
    }
  }
  this.downloadCsv('periods.csv', lines);
}

/** Download the people of the whole tree, re-read from the store, as a CSV file: this sheet's first
 *  in list order, then the other sheets' of its tree by sheet id, with sheet, name, grade in force on
 *  that sheet's today and due-total as that sheet shows it. */
protected async exportTree(): Promise<void> {
  const sheet = this.session.sheetId();
  if (!sheet) return;
  const lines = [['sheet', 'name', 'grade', 'due-total']];
  for (const f of await this.treeSearchService.search(sheet, '')) {
    lines.push([f.sheet, f.name, f.grade ?? '', f.dueTotal]);
  }
  this.downloadCsv('tree.csv', lines);
}

/** Download the person's statement as a CSV file: each claim of theirs their last statement bound,
 *  oldest first, with number, date, amount, the bound figure as the claim shows it, and status. */
protected async exportStatement(person: Person): Promise<void> {
  if (!(await this.readDone())) return;
  const last = this.lastStatementOf(person.id);
  const lines = [['number', 'date', 'amount', 'figure', 'status']];
  for (const c of [...this.claimsOf(person.id)].reverse()) {
    if (last === null || !c.stated || c.statedBy !== last.id) continue;
    const figure = claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id));
    lines.push([c.number ?? '', c.date, c.amount, figure === null ? 'n/a' : money(figure), c.status]);
  }
  this.downloadCsv('statement.csv', lines);
}

/** Wait for the sheet's last read, as of the date set when one is, to be shown, so an export taken
 *  just after a load shows what it read; false when no sheet is loaded. */
private async readDone(): Promise<boolean> {
  // A load just made starts its read once the view next updates.
  while (this.readLoad !== this.session.loads()) await new Promise((done) => setTimeout(done));
  let reading: Promise<void>;
  do {
    reading = this.reading;
    await reading;
  } while (reading !== this.reading);
  return this.sheet() !== null;
}

/** Download the lines as a CSV file of the name, each field quoted when it needs to be. */
private downloadCsv(name: string, lines: string[][]): void {
  const text = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([text], { type: 'text/csv' }));
  const link = this.document.createElement('a');
  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url));
}

/** The value the person is sorted on under `key`; null (n/a) sorts last. */
private sortValueOf(person: Person, key: Exclude<SortKey, 'added'>): string | number | null {
  switch (key) {
    case 'name':
      return nameKey(person.name);
    case 'grade':
      return this.gradeNow(person);
    case 'due-total':
      return this.dueCentsOf(person);
  }
}

